/**  A buff that at least one good roll allows. */
"wanted" | 
/**  A buff no good roll includes, or a curse on a stat no good roll uses. */
"useless" | 
/**  A curse the good rolls list as harmless. */
"harmless" | 
/**  A curse on a stat that at least one good roll uses. */
"harmful";

